      if (Fast charging inactive?) then (yes)
        :Shut down and end;
        stop
      else (no)
        if (BMS-fast charger handshake flag = 1?) then (yes)
          :Transition to State 156;
          stop
        elseif (DCDC state = 1?) then (yes)
          :Stay in State 155;
        elseif (3 seconds pass?) then (yes)
          :Move to State 157;
          stop
        else (no)
          :Move to State 157;
          stop
        endif
      endif
    fork again
      :EAS State Monitoring;
      if (Fast charging inactive?) then (yes)
        :Shut down and end;
        stop
      else (no)
        if (Handshake flag = 1?) then (yes)
          :Switch to State 156;
          stop
        elseif (EAS state = 1?) then (yes)
          :Remain in State 155;
        elseif (3 seconds elapse?) then (yes)
          :Shift to State 157;
          stop
        else (no)
          :Shift to State 157;
          stop
        endif
      endif
    fork again
      :Power Battery Current Monitoring;
      if (Fast charging stops?) then (yes)
        :Shut down and end;
        stop
      else (no)
        if (Handshake flag = 1?) then (yes)
          :Advance to State 156;
          stop
        elseif (Current = 6.1?) then (yes)
          :Maintain State 155;
        elseif (3 seconds pass?) then (yes)
          :Proceed to State 157;
          stop
        else (no)
          :Proceed to State 157;
          stop
        endif
      endif
    fork again
      :WTCH State Monitoring (Condition 1);
      if (Fast charging inactive?) then (yes)
        :Shut down and exit;
        stop
      else (no)
        if (Handshake flag = 1?) then (yes)
          :Change to State 156;
          stop
        elseif (WTCH state = 1?) then (yes)
          :Continue in State 155;
        else (no)
          :Transition to State 157;
          stop
        endif
      endif
    fork again
      :WTCH State Monitoring (Condition 2);
      if (Fast charging deactivates?) then (yes)
        :Shut down and conclude;
        stop
      else (no)
        if (Handshake flag = 1?) then (yes)
          :Enter State 156;
          stop
        elseif (WTCH state = 3?) then (yes)
          :Persist in State 155;
        else (no)
          :Switch to State 157;
          stop
        endif
      endif
    end fork

  else (no)
    :End process;
    stop
  endif
else (no)
  :End process;
  stop
endif
